updateCoins();renderSkins();renderLeader();updateMission();if(data.profile){$('#greeting').textContent=(lang==='id'?'Ayo, ':'Let’s go, ')+data.profile.name+'!';$('#start-overlay').classList.add('hidden')}

let W=900,H=500,dpr=1;function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);W=900;H=500;ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0)}new ResizeObserver(resize).observe(canvas);resize();
const game={running:false,paused:false,over:false,score:0,runCoins:0,life:3,lane:1,targetLane:1,jump:0,jumpVel:0,anim:0,speed:5,spawn:0,objects:[],last:0,elapsed:0,flash:0,dribble:0};
function startRun(){game.running=true;game.paused=false;game.over=false;game.score=0;game.runCoins=0;game.life=3;game.lane=1;game.targetLane=1;game.jump=0;game.jumpVel=0;game.anim=0;game.speed=5;game.spawn=50;game.objects=[];game.elapsed=0;game.flash=0;game.last=performance.now();$('#score').textContent='0';$('#hearts').textContent='♥ ♥ ♥';$('#message-overlay').classList.add('hidden');$('#start-overlay').classList.add('hidden');$('#pause-btn').textContent='Ⅱ';requestAnimationFrame(frame)}
function showMessage(title,copy,secondary,primary,secondAction,mainAction){$('#message-title').textContent=title;$('#message-copy').textContent=copy;$('#message-secondary').textContent=secondary;$('#message-primary').textContent=primary;$('#message-overlay').classList.remove('hidden');$('#message-secondary').onclick=secondAction;$('#message-primary').onclick=mainAction}
function pauseRun(){if(!game.running||game.over)return;game.paused=true;showMessage(tr('pauseTitle'),tr('pauseCopy'),tr('back'),tr('resume'),()=>{$('#message-overlay').classList.add('hidden');game.paused=false;game.last=performance.now();requestAnimationFrame(frame)},()=>{$('#message-overlay').classList.add('hidden');game.paused=false;game.running=false;$('#start-overlay').classList.remove('hidden')})}
function endRun(){game.running=false;game.over=true;data.best=Math.max(data.best,game.score);if(game.score>0){const prev=data.leader.find(x=>x.name===data.profile.name);if(prev)prev.score=Math.max(prev.score,game.score);else data.leader.push({name:data.profile.name,score:game.score});}store.save();renderLeader();showMessage(tr('gameOver'),`${data.profile?.name||'Player'}, ${game.score} ${tr('scoreLabel')} · +${game.runCoins} ${tr('earned').toLowerCase()}`,tr('back'),tr('runAgain'),()=>{$('#message-overlay').classList.add('hidden');$('#start-overlay').classList.remove('hidden')},startRun)}
function setLane(dir){if(!game.running||game.paused)return;game.targetLane=Math.max(0,Math.min(2,game.targetLane+dir));game.dribble=16}
function jump(){if(game.running&&!game.paused&&game.jump<=0){game.jumpVel=12.5;game.jump=1}}
$('#player-form').addEventListener('submit',e=>{e.preventDefault();data.profile={name:$('#kid-name').value.trim(),age:+$('#kid-age').value,school:$('#kid-school').value.trim(),phone:$('#parent-phone').value.trim()};store.save();$('#greeting').textContent=(lang==='id'?'Ayo, ':'Let’s go, ')+data.profile.name+'!';renderLeader();startRun()});$('#jump-btn').addEventListener('pointerdown',e=>{e.preventDefault();jump()});$('#pause-btn').onclick=pauseRun;
let touchX=0,touchY=0;canvas.addEventListener('pointerdown',e=>{touchX=e.clientX;touchY=e.clientY;canvas.setPointerCapture?.(e.pointerId)});canvas.addEventListener('pointerup',e=>{const dx=e.clientX-touchX,dy=e.clientY-touchY;if(Math.abs(dx)>25){setLane(dx>0?1:-1)}else if(dy<-20)jump()});window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp',' ','Space'].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft'||e.key==='a')setLane(-1);if(e.key==='ArrowRight'||e.key==='d')setLane(1);if(e.key==='ArrowUp'||e.key===' '||e.key==='Space')jump();if(e.key==='Escape')pauseRun()});
function addObject(){const lane=Math.floor(Math.random()*3),cone=Math.random()<.54;game.objects.push({x:W+35,lane,type:cone?'cone':'ball',hit:false,spin:Math.random()*6})}
function frame(now){if(!game.running||game.paused)return;const dt=Math.min((now-game.last)/16.67,2);game.last=now;game.elapsed+=dt;game.anim+=dt;game.speed=Math.min(9,5+game.elapsed*.001);game.score+=Math.max(1,Math.floor(dt));game.spawn-=dt;if(game.spawn<=0){addObject();game.spawn=52+Math.random()*40-game.speed*2}game.lane+=(game.targetLane-game.lane)*Math.min(.25,dt*.22);if(game.jump>0){game.jump+=game.jumpVel*dt*.09;game.jumpVel-=.72*dt;if(game.jump<=0){game.jump=0;game.jumpVel=0}}if(game.dribble>0)game.dribble-=dt;if(game.flash>0)game.flash-=dt;
const playerX=205+game.lane*5,ground=388;for(let i=game.objects.length-1;i>=0;i--){const o=game.objects[i];o.x-=game.speed*dt;if(!o.hit&&o.x<playerX+38&&o.x>playerX-25&&Math.abs(o.lane-game.lane)<.55){if(o.type==='ball'){o.hit=true;game.score+=100;game.runCoins+=5;data.coins+=5;data.mission=Math.min(10,data.mission+1);if(data.mission>=10&&!data.missionClaimed){data.missionClaimed=true;data.coins+=25;toast(tr('missionDone'))}updateCoins();updateMission()}else if(game.jump<.55){o.hit=true;game.life--;game.flash=14;$('#hearts').textContent=Array.from({length:3},(_,n)=>n<game.life?'♥':'♡').join(' ');if(game.life<=0){endRun();return}}}if(o.x<-50||o.hit)game.objects.splice(i,1)}$('#score').textContent=game.score.toLocaleString();draw();requestAnimationFrame(frame)}
function rr(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function draw(){ctx.clearRect(0,0,W,H);const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#8de0d3');sky.addColorStop(.64,'#cbf0d7');sky.addColorStop(.65,'#efca86');sky.addColorStop(1,'#e4ad62');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
// sunny court skyline
ctx.fillStyle='#ffe279';ctx.beginPath();ctx.arc(754,95,43,0,Math.PI*2);ctx.fill();ctx.fillStyle='#77c8aa';for(let i=0;i<5;i++){const x=((i*210-game.anim*.25)%1150+1150)%1150-100;rr(x,168,120,105,14,i%2?'#5db69d':'#65c2a8');ctx.fillStyle='#d9f3c8';for(let k=0;k<4;k++)rr(x+15+k*24,183,12,22,4,'#d9f3c8');ctx.fillStyle=i%2?'#5db69d':'#65c2a8'}
// basketball hoop
ctx.strokeStyle='#fff9dd';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(815,204);ctx.lineTo(815,118);ctx.lineTo(855,118);ctx.stroke();ctx.fillStyle='#fff6df';ctx.fillRect(810,112,54,38);ctx.strokeStyle='#f07442';ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(829,153,23,6,0,0,Math.PI);ctx.stroke();ctx.strokeStyle='#fff5df';ctx.lineWidth=1.5;for(let i=0;i<5;i++){ctx.beginPath();ctx.moveTo(811+i*9,155);ctx.lineTo(817+i*6,174);ctx.stroke()}
// stands and court
ctx.fillStyle='#f4bf72';ctx.fillRect(0,245,W,66);for(let r=0;r<3;r++){ctx.fillStyle=['#df7659','#f4e3a8','#d97858'][r];for(let i=0;i<18;i++){const x=i*58-((game.anim*.65)%58);rr(x,252+r*18,32,12,5,ctx.fillStyle)}}ctx.fillStyle='#f5d490';ctx.fillRect(0,305,W,29);ctx.fillStyle='#ca844d';ctx.fillRect(0,334,W,166);ctx.fillStyle='#e49e5c';ctx.fillRect(0,335,W,12);ctx.strokeStyle='#ffdfa1';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,424);ctx.lineTo(W,424);ctx.stroke();ctx.beginPath();ctx.arc(770,424,73,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.arc(770,424,39,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.moveTo(23,350);ctx.lineTo(23,500);ctx.moveTo(23,350);ctx.lineTo(164,350);ctx.stroke();
// speed accents
for(let i=0;i<7;i++){const x=((i*145-game.anim*game.speed*1.6)%1050+1050)%1050;rr(x,315+(i%3)*8,36,3,2,'#fff2c2')}
// objects
for(const o of game.objects){const y=390-o.lane*2.7;if(o.type==='cone'){ctx.fillStyle='#9a5c36';ctx.beginPath();ctx.ellipse(o.x,y+3,18,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ff753e';ctx.beginPath();ctx.moveTo(o.x,y-32);ctx.lineTo(o.x-15,y+1);ctx.lineTo(o.x+15,y+1);ctx.closePath();ctx.fill();ctx.fillStyle='#ffe3a2';ctx.fillRect(o.x-9,y-12,18,4);ctx.fillStyle='#fff8e9';ctx.fillRect(o.x-18,y,36,5)}else{ctx.save();ctx.translate(o.x,y-14+Math.sin(game.anim*.2+o.spin)*4);ctx.rotate(game.anim*.04+o.spin);ctx.fillStyle='#ffca3f';ctx.beginPath();ctx.arc(0,0,14,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#a95a2e';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,13,-1,1);ctx.moveTo(-13,0);ctx.quadraticCurveTo(0,-5,13,0);ctx.stroke();ctx.restore()}}
// player shadow + jump height
const px=205+game.lane*5, lift=game.jump*27, py=388-lift;ctx.fillStyle='#794c31';ctx.globalAlpha=.22;ctx.beginPath();ctx.ellipse(px,394,28-Math.min(10,game.jump*6),8,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
// player leg animation
const run=Math.sin(game.anim*.38), legY=py+53;ctx.strokeStyle='#27394b';ctx.lineWidth=12;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(px-5,py+34);ctx.lineTo(px-10+run*9,legY+9);ctx.lineTo(px-19+run*13,legY+13);ctx.moveTo(px+6,py+34);ctx.lineTo(px+10-run*9,legY+6);ctx.lineTo(px+24-run*13,legY+13);ctx.stroke();rr(px-28+run*13,legY+5,23,10,5,'#fff2de');rr(px+12-run*13,legY+5,23,10,5,'#fff2de');
// jersey body/head
ctx.fillStyle='#eaa36e';ctx.beginPath();ctx.arc(px,py-2,18,0,Math.PI*2);ctx.fill();ctx.fillStyle='#3d2927';ctx.beginPath();ctx.arc(px-1,py-9,19,Math.PI,Math.PI*2);ctx.lineTo(px+17,py-4);ctx.quadraticCurveTo(px+2,py-14,px-14,py-6);ctx.fill();ctx.fillStyle='#fffdf1';ctx.beginPath();ctx.arc(px+7,py,2.1,0,Math.PI*2);ctx.fill();ctx.fillStyle='#27394b';ctx.beginPath();ctx.arc(px+7.5,py,1,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#914e3b';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(px+7,py+6,4,.1,1.9);ctx.stroke();
const shirt=skinData.find(s=>s.id===data.skin)||skinData[0];ctx.fillStyle=shirt.shirt;ctx.beginPath();ctx.moveTo(px-18,py+16);ctx.lineTo(px-26,py+21);ctx.lineTo(px-20,py+31);ctx.lineTo(px-14,py+28);ctx.lineTo(px-12,py+46);ctx.quadraticCurveTo(px,py+52,px+14,py+45);ctx.lineTo(px+15,py+27);ctx.lineTo(px+22,py+29);ctx.lineTo(px+27,py+19);ctx.lineTo(px+17,py+14);ctx.lineTo(px+11,py+17);ctx.lineTo(px-10,py+17);ctx.closePath();ctx.fill();ctx.fillStyle=shirt.trim;ctx.fillRect(px-11,py+43,23,3);ctx.fillStyle='#fff';ctx.font='bold 10px sans-serif';ctx.textAlign='center';ctx.fillText('ADA',px,py+33);ctx.fillStyle='#f4ad30';ctx.beginPath();ctx.arc(px+25,py+36+Math.sin(game.anim*.35)*5,10,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#9c582e';ctx.lineWidth=1.3;ctx.beginPath();ctx.arc(px+25,py+36+Math.sin(game.anim*.35)*5,9,-1,1);ctx.moveTo(px+16,py+36+Math.sin(game.anim*.35)*5);ctx.quadraticCurveTo(px+25,py+32+Math.sin(game.anim*.35)*5,px+34,py+36+Math.sin(game.anim*.35)*5);ctx.stroke();
if(game.dribble>0){ctx.fillStyle='#fff';ctx.font='bold 13px sans-serif';ctx.textAlign='center';ctx.fillText('DRIBBLE!',px,py-36)}if(game.flash>0){ctx.fillStyle=`rgba(255,85,65,${game.flash/45})`;ctx.fillRect(0,0,W,H)}
}

